app.MapGet("/health",()=>Results.Ok(new{service="DadoHome.Api",status="ok"}));app.MapGet("/api/order-options",(IConfiguration cfg)=>Results.Ok(new{deliveryFee=Math.Max(0m,cfg.GetValue<decimal?>("Orders:DeliveryFee")??0m),pickupFee=0m,reservationMinutes=Math.Clamp(cfg.GetValue<int?>("Orders:ReservationMinutes")??20,5,120)}));app.MapPost("/api/auth/otp/request",(OtpRequest r,OtpService otp,IHostEnvironment env)=>{if(string.IsNullOrWhiteSpace(r.Phone))return Results.BadRequest();var code=otp.Issue(r.Phone);return Results.Ok(env.IsDevelopment()?new{sent=true,devCode=code}:new{sent=true});});app.MapPost("/api/auth/otp/verify",async(OtpVerify r,OtpService otp,JwtService jwt,DadoDbContext db)=>{if(!otp.Verify(r.Phone,r.Code))return Results.Unauthorized();var user=await db.Customers.FirstOrDefaultAsync(x=>x.Phone==r.Phone);if(user is null){user=new Customer{Id=Guid.NewGuid(),Phone=r.Phone};db.Customers.Add(user);db.Wallets.Add(new Wallet{Id=Guid.NewGuid(),CustomerId=user.Id});await db.SaveChangesAsync();}return Results.Ok(new{accessToken=jwt.Create(user.Id,user.Phone,Roles.Customer),expiresIn=1800});});app.MapPost("/api/admin/auth/login",async(StaffLoginRequest r,DadoDbContext db,PasswordService passwords,JwtService jwt)=>{var s=await db.StaffUsers.SingleOrDefaultAsync(x=>x.Phone==r.Phone&&x.IsActive);if(s is null||!passwords.Verify(r.Password,s.PasswordHash))return Results.Unauthorized();return Results.Ok(new{accessToken=jwt.Create(s.Id,s.Phone,s.Role),expiresIn=1800,user=new{s.Id,s.Name,s.Phone,s.Role}});});app.MapGet("/api/admin/me",async(ClaimsPrincipal user,DadoDbContext db)=>{var id=U(user);if(id is null)return Results.Unauthorized();var s=await db.StaffUsers.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id&&x.IsActive);return s is null?Results.Unauthorized():Results.Ok(new{s.Id,s.Name,s.Phone,s.Role});}).RequireAuthorization(p=>p.RequireRole(Roles.Administrator,Roles.OrderManager,Roles.Finance,Roles.Support));
