app.MapPost("/api/orders",async(CreateOrderRequest r,ClaimsPrincipal user,DadoDbContext db,IConfiguration cfg)=>{var customerId=U(user);if(customerId is null)return Results.Unauthorized();var delivery=r.DeliveryMethod?.Trim();if(delivery!="Courier"&&delivery!="Pickup")return Results.BadRequest(new{error="InvalidDeliveryMethod"});if(string.IsNullOrWhiteSpace(r.RecipientName)||string.IsNullOrWhiteSpace(r.RecipientPhone))return Results.BadRequest(new{error="RecipientRequired"});if(delivery=="Courier"&&string.IsNullOrWhiteSpace(r.DeliveryAddress))return Results.BadRequest(new{error="DeliveryAddressRequired"});if(r.Items.Count==0||r.Items.Any(x=>x.Quantity<=0||x.Quantity>100))return Results.BadRequest(new{error="InvalidItems"});var grouped=r.Items.GroupBy(x=>new{x.ProductId,x.Variant}).Select(g=>new CreateOrderItem(g.Key.ProductId,g.Key.Variant,g.Sum(x=>x.Quantity))).ToList();var ids=grouped.Select(x=>x.ProductId).Distinct().ToList();await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var products=await db.Products.Where(x=>ids.Contains(x.Id)&&x.IsActive).ToDictionaryAsync(x=>x.Id);if(products.Count!=ids.Count)return Results.BadRequest(new{error="ProductUnavailable"});foreach(var x in grouped)if(products[x.ProductId].Stock<x.Quantity)return Results.Conflict(new{error="InsufficientStock",productId=x.ProductId,available=products[x.ProductId].Stock});var subtotal=grouped.Sum(x=>products[x.ProductId].Price*x.Quantity);var deliveryFee=delivery=="Courier"?Math.Max(0m,cfg.GetValue<decimal?>("Orders:DeliveryFee")??0m):0m;var order=new Order{Id=Guid.NewGuid(),CustomerId=customerId.Value,Number=$"DH-{DateTime.UtcNow:yyyyMMdd}-{Guid.NewGuid().ToString("N")[..8].ToUpperInvariant()}",Status="Created",StockState="Reserved",DeliveryMethod=delivery,RecipientName=r.RecipientName.Trim(),RecipientPhone=r.RecipientPhone.Trim(),DeliveryAddress=delivery=="Courier"?r.DeliveryAddress.Trim():"",DeliveryComment=r.DeliveryComment?.Trim()??"",Subtotal=subtotal,DeliveryFee=deliveryFee,PaymentMethod=r.PaymentMethod,Total=subtotal+deliveryFee};db.Orders.Add(order);foreach(var x in grouped){var p=products[x.ProductId];p.Stock-=x.Quantity;db.OrderItems.Add(new OrderItem{Id=Guid.NewGuid(),OrderId=order.Id,ProductId=p.Id,ProductName=p.Name,Variant=x.Variant,Quantity=x.Quantity,UnitPrice=p.Price});}db.AuditLogs.Add(new AuditLog{Id=Guid.NewGuid(),ActorId=customerId.Value.ToString(),Role=Roles.Customer,Action="ORDER_CREATED_STOCK_RESERVED",Entity="Order",EntityId=order.Id.ToString()});await db.SaveChangesAsync();await tx.CommitAsync();return Results.Created($"/api/orders/{order.Id}",order);}).RequireAuthorization(p=>p.RequireRole(Roles.Customer));app.MapGet("/api/me/orders",async(ClaimsPrincipal user,DadoDbContext db)=>{var id=U(user);return id is null?Results.Unauthorized():Results.Ok(await db.Orders.Where(x=>x.CustomerId==id).OrderByDescending(x=>x.CreatedAt).ToListAsync());}).RequireAuthorization(p=>p.RequireRole(Roles.Customer));
app.MapGet("/api/wallet",async(ClaimsPrincipal user,DadoDbContext db,PaymentService ps)=>{var id=U(user);if(id is null)return Results.Unauthorized();var w=await db.Wallets.SingleAsync(x=>x.CustomerId==id);return Results.Ok(new{id=w.Id,currency=w.Currency,balance=await ps.WalletBalance(id.Value),transactions=await db.WalletEntries.Where(x=>x.WalletId==w.Id).OrderByDescending(x=>x.CreatedAt).Take(50).ToListAsync()});}).RequireAuthorization(p=>p.RequireRole(Roles.Customer));app.MapPost("/api/payments/intents",async(PaymentIntentRequest r,ClaimsPrincipal user,PaymentService ps)=>{var id=U(user);return id is null?Results.Unauthorized():Results.Ok(await ps.CreateIntent(id.Value,r));}).RequireAuthorization(p=>p.RequireRole(Roles.Customer));app.MapPost("/api/wallet/pay",async(WalletPayRequest r,ClaimsPrincipal user,DadoDbContext db,PaymentService ps)=>{var id=U(user);if(id is null)return Results.Unauthorized();var order=await db.Orders.SingleOrDefaultAsync(x=>x.Id==r.OrderId&&x.CustomerId==id);if(order is null)return Results.NotFound();if(order.Status!="Created"||order.StockState!="Reserved")return Results.Conflict(new{error="OrderNotPayable"});await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);if(await ps.WalletBalance(id.Value)<order.Total)return Results.BadRequest(new{error="InsufficientBalance"});var w=await db.Wallets.SingleAsync(x=>x.CustomerId==id);if(await db.WalletEntries.AnyAsync(x=>x.ExternalId==$"order:{order.Id}"))return Results.Ok(new{paid=true,order.Id,order.Total});db.WalletEntries.Add(new WalletEntry{Id=Guid.NewGuid(),WalletId=w.Id,OrderId=order.Id,Amount=-order.Total,Type="OrderPayment",Status="Successful",ExternalId=$"order:{order.Id}"});order.Status="Paid";order.StockState="Committed";order.StockCommittedAt=DateTime.UtcNow;db.AuditLogs.Add(new AuditLog{Id=Guid.NewGuid(),ActorId=id.Value.ToString(),Role=Roles.Customer,Action="WALLET_PAYMENT_SUCCESS_STOCK_COMMITTED",Entity="Order",EntityId=order.Id.ToString()});await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(new{paid=true,order.Id,order.Total});}).RequireAuthorization(p=>p.RequireRole(Roles.Customer));app.MapPost("/api/payments/webhook",async(HttpRequest req,PaymentService ps)=>{using var sr=new StreamReader(req.Body);var body=await sr.ReadToEndAsync();var sig=req.Headers["X-Dado-Signature"].ToString();if(string.IsNullOrWhiteSpace(sig)||!ps.VerifyWebhook(body,sig))return Results.Unauthorized();var e=JsonSerializer.Deserialize<PaymentWebhook>(body,new JsonSerializerOptions{PropertyNameCaseInsensitive=true});return e is null?Results.BadRequest():await ps.ApplyWebhook(e)?Results.Ok():Results.NotFound();});
